var i=7;var a=`007-recipe-ratios-yields-and-portions`;var o=`001`;var s={en:`Recipe Ratios, Yields, and Portions`,ua:`Пропорції, вихід готової страви та порції`};var r={short:`Recipe ratios express the relationship between ingredient quantities, while yield shows how much usable food remains after preparation and cooking. Together with portion size, these concepts help cooks scale recipes, shop accurately, and control cost.`,sections:[{title:`Core idea`,text:`Purchased weight, edible prepared weight and final cooked weight are different measurements. Peeling removes inedible material; heating can remove water or add absorbed liquid. A serving specification should say whether its mass is raw or cooked.`},{title:`Scientific / practical principles`,text:`Preparation yield percentage equals usable prepared mass divided by purchased mass, multiplied by 100. Cooking yield percentage compares cooked weight with the weight entering the cooking step. Both depend on cut size and method.`},{title:`How to apply it`,text:`Standardize portion sizes with a scale or ladle, record real yields during test cooking, and calculate purchase quantities from desired edible amounts. Recheck seasoning and vessel capacity when increasing batch size.`},{title:`Practical example`,text:`If 1.2 kg of carrots becomes 1.0 kg after peeling and trimming, preparation yield is about 83%. To obtain 2.0 kg of prepared carrots at the same yield, buy approximately 2.4 kg.`},{title:`Common mistakes and limitations`,text:`Do not assume 200 g raw rice makes a 200 g cooked portion, or multiply serving count without checking losses and gains. Confusing raw and cooked weights can distort nutrition and cost calculations.`},{title:`Additional application`,text:`A ratio describes relationships independently of batch size. For example, a 2:1 water-to-rice ratio scales from 200 g + 100 g to 600 g + 300 g, but actual rice hydration depends on variety, pot shape and evaporation; always verify the method. Separately calculate edible yield and cooked yield before estimating portions.`}]};var n={short:`Пропорції описують співвідношення інгредієнтів, а вихід показує, скільки придатного продукту залишиться після підготовки та приготування. Разом із розміром порції вони допомагають масштабувати рецепти, планувати закупівлі та контролювати витрати.`,sections:[{title:`Суть`,text:`Маса закупленого продукту, маса їстівної підготовленої частини та маса готової страви це різні величини. Очищення зменшує масу, а приготування може випаровувати воду чи, навпаки, додавати поглинуту рідину. Для порції уточнюйте, йдеться про сирий чи готовий продукт.`},{title:`Наукові та практичні принципи`,text:`Відсоток виходу після підготовки дорівнює масі придатної частини, поділеній на закуплену масу й помноженій на 100. Вихід після приготування порівнює готову масу з масою перед нагріванням. Значення залежать від техніки.`},{title:`Як застосовувати`,text:`Стандартизуйте порції вагами або ополоником, записуйте фактичний вихід під час тестових приготувань і розраховуйте закупівлю від бажаної їстівної маси. Під час збільшення партії окремо перевіряйте посуд і приправляння.`},{title:`Практичний приклад`,text:`Якщо після очищення з 1,2 кг моркви залишився 1,0 кг, вихід становить приблизно 83%. Щоб отримати 2,0 кг очищеної моркви за такого самого виходу, потрібно закупити близько 2,4 кг.`},{title:`Поширені помилки й обмеження`,text:`Не припускайте, що 200 г сирого рису дорівнюють 200 г готової каші, і не масштабуйте порції без урахування втрат та поглинання води. Плутанина між сирою й готовою масою спотворює калорійність і собівартість.`},{title:`Додаткове застосування`,text:`Пропорція показує співвідношення незалежно від розміру партії. Наприклад, співвідношення води до рису 2:1 можна масштабувати з 200 г + 100 г до 600 г + 300 г, але реальна потреба у воді залежить від сорту, посуду й випаровування. Окремо визначайте вихід після очищення та після приготування, перш ніж розраховувати порції.`}]};var c=[4,6,266,273];var l=`References / Джерела`;var d=[`https://www.nist.gov/pml/owm/nist-metric-recipes-sp-1290`,`https://www.ciachef.edu/online-resources/`];var p={id:7,slug:a,group:`001`,title:s,en:r,ua:n,related:c,referenceTitle:l,references:d};export{p as default,r as en,o as group,i as id,l as referenceTitle,d as references,c as related,a as slug,s as title,n as ua};